INSERT INTO feature VALUES('session-readmission','sessions','Sessions replayed by the kernel','session-types','implemented','notable',NULL,'Readmission erases the session discipline and the kernel replays what a session computes: a session type crosses as the kernel''s session code at the state it stands at, the protocol unfolded there when the state is past its root; a send crosses as its payload returned at the type it was checked at, a select and a close as the unit, a fork as its child and then its parent. A receive crosses as its body reading the received value from an assumption of the value''s type, and an offer as a case on an assumed choice among its arms, each assumption an axiom named in the audit of whatever reads it; an endpoint, sent or received, names no value and needs none.','core-checker','crates/core-checker-base/src/judgement/session/tests.rs crates/core-checker-base/tests/judgement/session.rs crates/core-checker-bridge/src/bridge/tests.rs crates/surface-dispatcher/src/compose.rs corpus/model/sessions/seat-exchange.gandr corpus/model/sessions/receive-payload.gandr','corpus/model/sessions/seat-exchange.gandr',NULL);
